import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    strings = input[1:]

    max_beauty = 0
    current_char = None
    current_count = 0

    for s in strings:
        if not s:
            continue
        first_char = s[0]
        last_char = s[-1]

        if current_char == first_char:
            current_count += 1
        else:
            current_count = 1

        max_beauty = max(max_beauty, current_count)

        for char in s[1:]:
            if char == last_char:
                current_count += 1
            else:
                current_count = 1
            max_beauty = max(max_beauty, current_count)

        current_char = last_char

    print(max_beauty)

if __name__ == "__main__":
    main()
